let BGS=null;
async function backgrounds(){if(BGS)return BGS;const im=await loadImg('bg_01_room_wide');if(!im)throw Error('S30 missing original bg_01_room_wide');
 const north=new OffscreenCanvas(im.width,im.height);north.getContext('2d').drawImage(im,0,0);
 const wide=new OffscreenCanvas(W,H),x=wide.getContext('2d');x.filter='blur(9px)';x.drawImage(im,378,295,65,270,-30,-20,W+60,H+40);x.filter='blur(3px)';x.drawImage(im,820,620,300,230,-20,875,W+40,245);x.filter='none';x.fillStyle='rgba(65,52,40,.16)';x.fillRect(0,873,W,7);x.drawImage(im,638,310,18,225,1130,0,62,875);x.fillStyle='rgba(48,32,22,.24)';x.fillRect(1192,0,16,875);return BGS={north,wide};}
const TV={src:[60,320,340,191]},k=W/TV.src[2],SCR=[[202,365],[282,367],[280,472],[202,472]].map(([x,y])=>[(x-TV.src[0])*k,(y-TV.src[1])*k]);
function tvScreen(x, t) {
  const [a, b, c, d] = SCR, cx = (a[0] + b[0] + c[0] + d[0]) / 4, cy = (a[1] + b[1] + c[1] + d[1]) / 4;
  const sw = (b[0] - a[0] + c[0] - d[0]) / 2, sh = (d[1] - a[1] + c[1] - b[1]) / 2;
  const u = t - T_TV_OFF;
  let sy = 1, sx = 1, bright = 1, alpha = 1;
  if (u > 0) { sy = Math.max(0.006, 1 - u / 0.1); bright = 1 + 2 * Math.min(1, u / 0.1); if (u > 0.1) { sx = Math.max(0.012, 1 - (u - 0.1) / 0.14); } if (u > 0.24) alpha = Math.max(0, 1 - (u - 0.24) / 0.15); }
  if (alpha <= 0) return;
  x.save(); x.globalAlpha = alpha;
  x.beginPath(); x.roundRect(a[0] + 8, a[1] + 10, sw - 16, sh - 18, 46); x.clip();                 // 显像管玻璃是鼓的、圆角
  if (u > 0.1) x.globalCompositeOperation = 'lighter';
  x.translate(cx, cy); x.scale(sx, sy);
  if (u <= 0.1) {
    const g = x.createLinearGradient(0, -sh / 2, 0, sh / 2); g.addColorStop(0, '#5aa9e6'); g.addColorStop(0.65, '#9fd6f5'); g.addColorStop(0.66, '#7cc56a'); g.addColorStop(1, '#4e9a45');
    x.fillStyle = g; x.fillRect(-sw / 2, -sh / 2, sw, sh);
    x.fillStyle = '#ffe680'; x.beginPath(); x.arc(sw * 0.25, -sh * 0.25, sh * 0.1, 0, 7); x.fill();
    const px = -sw * 0.35 + ((t * 0.35) % 1) * sw * 0.7, hop = Math.abs(Math.sin(t * 7)) * sh * 0.08;
    x.fillStyle = '#ff8a3d'; x.beginPath(); x.ellipse(px, sh * 0.12 - hop, sw * 0.07, sh * 0.06, 0, 0, 7); x.fill();
    x.fillStyle = 'rgba(0,0,0,0.12)'; for (let yy = -sh / 2; yy < sh / 2; yy += 6) x.fillRect(-sw / 2, yy, sw, 2);   // 扫描线
    if (u > 0) { x.fillStyle = `rgba(255,255,255,${Math.min(1, u / 0.1)})`; x.fillRect(-sw / 2, -sh / 2, sw, sh); }
  } else {
    const r = Math.max(sw, sh) * 0.6, g = x.createRadialGradient(0, 0, 0, 0, 0, r); g.addColorStop(0, `rgba(255,255,255,${Math.min(1, bright)})`); g.addColorStop(0.15, 'rgba(220,235,255,0.9)'); g.addColorStop(1, 'rgba(160,190,255,0)');
    x.fillStyle = g; x.fillRect(-sw / 2, -sh / 2, sw, sh);
  }
  x.restore();
}

function cord(x,s){x.save();x.lineCap='round';x.lineWidth=5;x.strokeStyle='rgba(62,42,30,.75)';x.beginPath();x.moveTo(...s.ropeTop);x.lineTo(...s.knob);x.stroke();x.lineWidth=3;x.strokeStyle='#e8e2cf';x.stroke();const[a,b]=s.knob;x.fillStyle='#d9c9a0';x.strokeStyle=LINE;x.lineWidth=2;x.beginPath();x.ellipse(a+.26,b+8.6,5,9,0,0,Math.PI*2);x.fill();x.stroke();x.restore()}
function shadows(x,s){x.save();x.filter=s.source.north?'blur(1px)':'blur(2px)';x.strokeStyle='rgba(45,29,20,.22)';x.fillStyle='rgba(45,29,20,.16)';x.lineCap='round';x.lineJoin='round';x.lineWidth=s.source.north?2:4;if(s.source.ground_contact_paths.length){for(const a of s.source.ground_contact_paths){x.beginPath();a.forEach((p,i)=>i?x.lineTo(...p):x.moveTo(...p));x.stroke()}}else{for(const p of s.source.support_toes_scene){x.beginPath();x.ellipse(p[0]-5,p[1]+1,8,2,0,0,Math.PI*2);x.fill()}}x.restore()}
