async function layer(s,t,bg){const c=new OffscreenCanvas(bg.width,bg.height),x=c.getContext('2d');if(s.branch==='north_tv'){x.save();x.translate(TV.src[0],TV.src[1]);x.scale(1/k,1/k);tvScreen(x,t);x.restore()}else cord(x,s);shadows(x,s);const im=await loadImg(s.source.url),m=s.source.matrix;if(!im)throw Error('S30 missing locked raw '+s.pose);x.save();x.transform(m[0][0],m[1][0],m[0][1],m[1][1],m[0][2],m[1][2]);x.drawImage(im,0,0);x.restore();return c}
